+models:
+  slots:
+    vision:
+      providerKind: openai-completions
+      baseUrl: https://api.openai.com/v1
+      modelId: gpt-4o
+''');
+      final baseline = loadCliConfig(tmp.path);
+      expect(baseline.models, isNotNull);
+      // Empty render = removal semantics for `models:` (saveCliConfig doc).
