// unwritable workspace .fah dir.
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

Future<void> main() async {
  final tmp = Directory.systemTemp.createTempSync('fah-review-2447-');
  final proj = Directory('${tmp.path}/proj');
  final global = File('${tmp.path}/.fah/config.yaml');
  global
    ..createSync(recursive: true)
    ..writeAsStringSync('mode: code\ntools:\n  web_search: false\n');
  final projectFile = File('${proj.path}/.fah/config.yaml');
  projectFile
    ..createSync(recursive: true)
    ..writeAsStringSync('tools:\n  web_search: false\n');
  // The workspace .fah dir is not this machine's to edit (ro mount / root-owned).
  Directory('${proj.path}/.fah').changePermissionsSync(0o555);

  final baseline = loadCliConfig(tmp.path);
  try {
    // What `/tools enable web_search global` triggers post-PR: persistConfig
    // -> saveCliConfig(base:, projectDir:, forceGlobal: false).
    await saveCliConfig(
      tmp.path,
      baseline.copyWith(tools: const ToolsConfig(tools: {'web_search': true})),
      base: baseline,
      projectDir: proj.path,
    );
    stdout.writeln('NO-THROW: global file now:');
    stdout.writeln(global.readAsStringSync());
    stdout.writeln('project file still:');
    stdout.writeln(projectFile.readAsStringSync());
  } on Object catch (error) {
    stdout.writeln('THREW: ${error.runtimeType}: $error');
  } finally {
    Directory('${proj.path}/.fah').changePermissionsSync(0o755);
    tmp.deleteSync(recursive: true);
  }
}

