// Review repro (PR #2447, writable workspace): where does the /tools
// GLOBAL-scope toggle land, and does every later persist rewrite the
// project file?
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';

Future<void> main() async {
  final tmp = Directory.systemTemp.createTempSync('fah-review-2447b-');
  final proj = Directory('${tmp.path}/proj');
  final global = File('${tmp.path}/.fah/config.yaml');
  global
    ..createSync(recursive: true)
    ..writeAsStringSync('mode: code\ntools:\n  web_search: false\n');
  final projectFile = File('${proj.path}/.fah/config.yaml');
  projectFile
    ..createSync(recursive: true)
    ..writeAsStringSync('tools:\n  web_search: false\n');

  final baseline = loadCliConfig(tmp.path);
  // `/tools enable web_search global` post-PR.
  await saveCliConfig(
    tmp.path,
    baseline.copyWith(tools: const ToolsConfig(tools: {'web_search': true})),
    base: baseline,
    projectDir: proj.path,
  );
  stdout.writeln(
    'after /tools global toggle, project file:\n${projectFile.readAsStringSync()}',
  );
  stdout.writeln(
    'after /tools global toggle, global file:\n${global.readAsStringSync()}',
  );

  // A later unrelated persist (`/mode architect`): does the project file
  // get rewritten again (mtime churn), and does the global tools block
  // ever catch up?
  final before = projectFile.statSync().modified;
  await Future<void>.delayed(const Duration(milliseconds: 20));
  await saveCliConfig(
    tmp.path,
    loadCliConfig(tmp.path).copyWith(mode: 'architect'),
    base: baseline,
    projectDir: proj.path,
  );
  final after = projectFile.statSync().modified;
  stdout.writeln(
    'project file rewritten by an unrelated /mode persist: '
    '${after.isAfter(before)}',
  );
  stdout.writeln(
    'global file after the /mode persist:\n${global.readAsStringSync()}',
  );
  tmp.deleteSync(recursive: true);
}

